import{_ as r,C as s,o,c as n,a2 as c,b as d,w as i,a as t,E as u,a3 as m,j as e}from"./chunks/framework.CgxQ0r6v.js";const q=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_2.md"}'),p={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-II/Lectura_Catedra_Evaluacion_2.md"};function A(v,a,b,h,P,g){const l=s("Mermaid");return o(),n("div",null,[a[1]||(a[1]=c('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-formulacion-del-proyecto-arbol-de-objetivos-y-eap" tabindex="-1">Eje Temático: Formulación del Proyecto (Árbol de Objetivos y EAP) <a class="header-anchor" href="#eje-tematico-formulacion-del-proyecto-arbol-de-objetivos-y-eap" aria-label="Permalink to &quot;Eje Temático: Formulación del Proyecto (Árbol de Objetivos y EAP)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-luz-al-final-del-tunel" tabindex="-1">🧭 Introducción: La Luz al Final del Túnel <a class="header-anchor" href="#🧭-introduccion-la-luz-al-final-del-tunel" aria-label="Permalink to &quot;🧭 Introducción: La Luz al Final del Túnel&quot;">​</a></h2><p>En la evaluación pasada, construimos un Árbol de Problemas que nos mostró una radiografía oscura y pesimista de la comunidad. Vimos fallas, equipos quemados y atrasos. Ahora, es el momento de ponerte la capa de ingeniero resolutivo. Vamos a transformar esa realidad negativa en una proyección optimista y alcanzable a través del <strong>Árbol de Objetivos</strong>.</p><hr><h2 id="🏛️-capitulo-i-el-arbol-de-objetivos-de-lo-negativo-a-lo-positivo" tabindex="-1">🏛️ CAPÍTULO I: El Árbol de Objetivos (De lo Negativo a lo Positivo) <a class="header-anchor" href="#🏛️-capitulo-i-el-arbol-de-objetivos-de-lo-negativo-a-lo-positivo" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Árbol de Objetivos (De lo Negativo a lo Positivo)&quot;">​</a></h2><p>La transición del Árbol de Problemas al Árbol de Objetivos es casi matemática. Consiste en reescribir absolutamente todas las tarjetas negativas en estados positivos y deseables.</p><h3 id="_1-1-el-objetivo-central-el-tronco" tabindex="-1">1.1 El Objetivo Central (El Tronco) <a class="header-anchor" href="#_1-1-el-objetivo-central-el-tronco" aria-label="Permalink to &quot;1.1 El Objetivo Central (El Tronco)&quot;">​</a></h3><p>El problema central se convierte en tu faro, en el <strong>Objetivo General</strong> del proyecto.</p><ul><li><em>Problema Central:</em> &quot;Alta inoperatividad de los equipos de computación&quot;.</li><li><em>Objetivo General:</em> &quot;Equipos de computación 100% operativos y optimizados&quot;.</li></ul><h3 id="_1-2-los-medios-las-raices" tabindex="-1">1.2 Los Medios (Las Raíces) <a class="header-anchor" href="#_1-2-los-medios-las-raices" aria-label="Permalink to &quot;1.2 Los Medios (Las Raíces)&quot;">​</a></h3><p>Las causas del problema ahora se convierten en los <strong>Medios</strong> que vas a utilizar para alcanzar tu objetivo.</p><ul><li><em>Causa:</em> &quot;Ausencia de mantenimiento preventivo&quot;.</li><li><em>Medio:</em> &quot;Mantenimiento preventivo ejecutado rigurosamente&quot;.</li><li><em>Causa:</em> &quot;Personal desconoce el uso del software libre&quot;.</li><li><em>Medio:</em> &quot;Personal capacitado en el uso de software libre&quot;.</li></ul><h3 id="_1-3-los-fines-las-ramas" tabindex="-1">1.3 Los Fines (Las Ramas) <a class="header-anchor" href="#_1-3-los-fines-las-ramas" aria-label="Permalink to &quot;1.3 Los Fines (Las Ramas)&quot;">​</a></h3><p>Los efectos negativos se transforman en los <strong>Fines</strong> o beneficios esperados si logras tu objetivo.</p><ul><li><em>Efecto:</em> &quot;Atraso en la carga de notas&quot;.</li><li><em>Fin:</em> &quot;Carga de notas ágil y oportuna&quot;.</li></ul><hr><h2 id="🧩-capitulo-ii-analisis-de-alternativas" tabindex="-1">🧩 CAPÍTULO II: Análisis de Alternativas <a class="header-anchor" href="#🧩-capitulo-ii-analisis-de-alternativas" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Análisis de Alternativas&quot;">​</a></h2><p>Cuando transformas las raíces (causas) en medios, te darás cuenta de que hay muchas formas de alcanzar el objetivo. Por ejemplo, para lograr &quot;Equipos operativos&quot;, podrías:</p><ul><li><strong>Alternativa A:</strong> Comprar 20 computadoras nuevas.</li><li><strong>Alternativa B:</strong> Reparar las computadoras existentes y dictar talleres de cuidado a los usuarios.</li></ul><p>Como estudiantes de Trayecto I de Informática Aplicada, su rol no es financiar compras millonarias, sino aplicar su fuerza técnica e intelectual. Por ende, la <strong>Alternativa B</strong> es la estrategia óptima, viable y que cumple con el Reglamento de la UPSIT en cuanto a contraste teórico-práctico.</p><hr><h2 id="🏗️-capitulo-iii-la-estructura-analitica-del-proyecto-eap" tabindex="-1">🏗️ CAPÍTULO III: La Estructura Analítica del Proyecto (EAP) <a class="header-anchor" href="#🏗️-capitulo-iii-la-estructura-analitica-del-proyecto-eap" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: La Estructura Analítica del Proyecto (EAP)&quot;">​</a></h2><p>Una vez seleccionada la estrategia óptima, construimos la EAP. Este es un diagrama jerárquico que desglosa el proyecto en niveles lógicos. Es el puente definitivo entre el árbol de objetivos y la matriz del marco lógico.</p><h3 id="_3-1-los-4-niveles-de-la-eap" tabindex="-1">3.1 Los 4 Niveles de la EAP <a class="header-anchor" href="#_3-1-los-4-niveles-de-la-eap" aria-label="Permalink to &quot;3.1 Los 4 Niveles de la EAP&quot;">​</a></h3><p>Se lee de arriba hacia abajo:</p><ol><li><strong>Fin:</strong> ¿Cuál es el impacto social mayor? (Ej. Mejorar la calidad educativa de la escuela).</li><li><strong>Propósito:</strong> ¿Cuál es el objetivo directo del proyecto? (Ej. Optimizar la sala de telemática).</li><li><strong>Componentes (Resultados):</strong> Son los &quot;entregables&quot; tangibles que le darás a la comunidad. <ul><li><em>Componente 1:</em> Hardware reparado.</li><li><em>Componente 2:</em> Software ofimático instalado.</li><li><em>Componente 3:</em> Personal capacitado (Alfabetización).</li></ul></li><li><strong>Actividades:</strong> ¿Qué tareas específicas debes hacer para entregar esos componentes? (Ej. Limpiar tarjetas madre, instalar Linux, dictar un taller de 2 horas).</li></ol><h3 id="_3-2-representacion-visual-de-la-eap" tabindex="-1">3.2 Representación Visual de la EAP <a class="header-anchor" href="#_3-2-representacion-visual-de-la-eap" aria-label="Permalink to &quot;3.2 Representación Visual de la EAP&quot;">​</a></h3>',30)),(o(),d(m,null,{default:i(()=>[u(l,{id:"mermaid-164",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20%25%25%20Nivel%201%3A%20Fin%0A%20%20%20%20F%5BFin%3A%20Mejorar%20calidad%20educativa%5D%0A%20%20%20%20%0A%20%20%20%20%25%25%20Nivel%202%3A%20Prop%C3%B3sito%0A%20%20%20%20P((Prop%C3%B3sito%3A%20Equipos%20100%25%20operativos))%0A%20%20%20%20F%20---%20P%0A%20%20%20%20%0A%20%20%20%20%25%25%20Nivel%203%3A%20Componentes%0A%20%20%20%20C1%5BC1%3A%20Hardware%20Reparado%5D%0A%20%20%20%20C2%5BC2%3A%20Software%20Instalado%5D%0A%20%20%20%20C3%5BC3%3A%20Personal%20Capacitado%5D%0A%20%20%20%20P%20---%20C1%0A%20%20%20%20P%20---%20C2%0A%20%20%20%20P%20---%20C3%0A%20%20%20%20%0A%20%20%20%20%25%25%20Nivel%204%3A%20Actividades%0A%20%20%20%20A1%5BA1.1%3A%20Limpieza%20F%C3%ADsica%5D%0A%20%20%20%20A2%5BA1.2%3A%20Cambio%20Capacitores%5D%0A%20%20%20%20A3%5BA2.1%3A%20Formateo%20de%20Disco%5D%0A%20%20%20%20A4%5BA3.1%3A%20Taller%20Ofim%C3%A1tica%5D%0A%20%20%20%20%0A%20%20%20%20C1%20---%20A1%0A%20%20%20%20C1%20---%20A2%0A%20%20%20%20C2%20---%20A3%0A%20%20%20%20C3%20---%20A4%0A%20%20%20%20%0A%20%20%20%20classDef%20proposito%20fill%3A%23ccffcc%2Cstroke%3A%2300aa00%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20P%20proposito%3B%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("div",{class:"important custom-block github-alert"},[e("p",{class:"custom-block-title"},"IMPORTANT"),e("p",null,[e("strong",null,"La Conexión Exacta"),t(" El nivel 4 de la EAP (Actividades) es vital. Si no sabes qué actividades exactas vas a realizar, no podrás calcular cuánto dinero necesitas ni cuánto tiempo te tomará. La EAP es el insumo principal para lo que haremos en las próximas dos evaluaciones: planificar el Cronograma y el Presupuesto.")])],-1))])}const C=r(p,[["render",A]]);export{q as __pageData,C as default};
